#[test]
fn a_rerun_after_a_kill_replaces_every_page_and_leaves_no_work_files() {
    let root = temp("rerun");
    let site = root.join("site");
    std::fs::create_dir_all(&site).unwrap();
    // b.html を退避した直後に止められた状態：a は新しく、b は本来の名前に無い
    std::fs::write(site.join("a.html"), "新しい a").unwrap();
    std::fs::write(site.join(".b.html.sas-bak"), "前の b").unwrap();
    std::fs::write(site.join(".b.html.sas-tmp"), "新しい b").unwrap();
    let pages = vec![
        ("a.html".to_string(), "新しい a".to_string()),
        ("b.html".to_string(), "新しい b".to_string()),
    ];
    OutDir::new(root.clone()).write_pages("site", &pages, &[]).unwrap();
    assert_eq!(std::fs::read_to_string(site.join("a.html")).unwrap(), "新しい a");
    assert_eq!(std::fs::read_to_string(site.join("b.html")).unwrap(), "新しい b");
    assert!(leftovers(&site).is_empty(), "作業用のファイルが残った：{:?}", leftovers(&site));
}
